import { ok } from './result.js';
import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';

export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter(inv =>
      ['issued', 'partially_paid'].includes(inv.status) &&
      daysBetween(inv.dueDate, asOf) > 0
    )
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

export function vatSummary(invoices) {
  const rateMap = new Map();

  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
      continue;
    }

    for (const line of invoice.lines) {
      const vatRate = line.vatRate ?? 0;

      const subtotal = line.qty * line.unitPrice;
      const discountPercent = line.discountPercent ?? 0;
      const afterDiscount = subtotal * (1 - discountPercent / 100);
      const vat = Math.max(0, Math.round(afterDiscount * (vatRate / 100)));

      if (!rateMap.has(vatRate)) {
        rateMap.set(vatRate, { baseSum: 0, vatSum: 0 });
      }
      const entry = rateMap.get(vatRate);
      entry.baseSum += afterDiscount;
      entry.vatSum += vat;
    }
  }

  const result = Array.from(rateMap.entries())
    .map(([rate, { baseSum, vatSum }]) => ({
      rate,
      base: Math.round(baseSum),
      vat: vatSum,
    }))
    .sort((a, b) => b.rate - a.rate);

  return ok(result);
}

export function lateFee(invoice, asOf) {
  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }

  const balance = balanceDue(invoice);
  const fee = balance * daysOverdue * 0.0004;
  return Math.round(fee);
}

