    assert(result.value.topCustomers[i].due >= result.value.topCustomers[i + 1].due);
  }
});

test('dashboard topCustomers includes all amounts due from a customer', () => {
  const invoice1 = makeIssuedInvoice('C-001', '2024-01-15');
  const invoice2 = makeIssuedInvoice('C-001', '2024-01-20');
  const invoices = [invoice1, invoice2];

  const result = dashboard(invoices, '2024-03-15');
  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers.length, 1);
  const totalDue = invoiceTotals(invoice1).total + invoiceTotals(invoice2).total;
  assert.equal(result.value.topCustomers[0].due, totalDue);
});

test('dashboard topCustomers excludes fully paid invoices', () => {
  const outstanding = makeIssuedInvoice('C-001', '2024-01-15');
  const paid = makePaidInvoice('C-001', '2024-01-15');
  const invoices = [outstanding, paid];

  const result = dashboard(invoices, '2024-03-15');
  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers.length, 1);
  const expectedDue = invoiceTotals(outstanding).total;
  assert.equal(result.value.topCustomers[0].due, expectedDue);
});

test('dashboard topCustomers handles partially paid invoices', () => {
  const invoice = makeIssuedInvoice('C-001', '2024-01-15');
  const totals = invoiceTotals(invoice);
  const paid = recordPayment(invoice, { amount: Math.floor(totals.total / 2) });

  const result = dashboard([paid.value], '2024-03-15');
  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers[0].customerId, 'C-001');
  assert.equal(result.value.topCustomers[0].due, Math.ceil(totals.total / 2));
});

test('dashboard returns fewer than 3 customers when not enough', () => {
  const invoice = makeIssuedInvoice('C-001', '2024-01-15');
  const invoices = [invoice];

  const result = dashboard(invoices, '2024-03-15');
  assert.equal(result.ok, true);
  assert.equal(result.value.topCustomers.length, 1);
});

test('dashboard with mixed invoice statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = makeIssuedInvoice('C-002', '2024-01-15');
  const partiallyPaid = (() => {
    const invoice = makeIssuedInvoice('C-003', '2024-01-15');
    const totals = invoiceTotals(invoice);
    return recordPayment(invoice, { amount: 1000 }).value;
  })();
  const paid = (() => {
    const invoice = makeIssuedInvoice('C-004', '2024-01-15');
    const totals = invoiceTotals(invoice);
    return makePaidInvoice('C-004', '2024-01-15', totals.total);
  })();

  const invoices = [draft, issued, partiallyPaid, paid];
  const result = dashboard(invoices, '2024-03-15');

  assert.equal(result.ok, true);
  assert.deepEqual(result.value.counts, {
    draft: 1,
    issued: 1,
    partially_paid: 1,
    paid: 1,
  });
  assert.equal(result.value.topCustomers.length, 2); // C-002 and C-003 have outstanding
});

test('dashboard outstanding with mix of paid and unpaid', () => {
  const issued = makeIssuedInvoice('C-001', '2024-01-15');
  const paid = (() => {
    const invoice = makeIssuedInvoice('C-002', '2024-01-15');
    const totals = invoiceTotals(invoice);
    return makePaidInvoice('C-002', '2024-01-15', totals.total);
  })();

  const result = dashboard([issued, paid], '2024-03-15');
  assert.equal(result.ok, true);
  const issuedTotals = invoiceTotals(issued);
  assert.equal(result.value.outstanding, issuedTotals.total);
});

test('dashboard all fields are present', () => {
  const invoices = [makeIssuedInvoice('C-001', '2024-01-15')];
  const result = dashboard(invoices, '2024-03-15');

  assert.equal(result.ok, true);
  assert(result.value.counts !== undefined);
  assert(result.value.outstanding !== undefined);
  assert(result.value.overdue !== undefined);
  assert(result.value.topCustomers !== undefined);
});

test('dashboard overdue has count and amount properties', () => {
  const invoices = [makeIssuedInvoice('C-001', '2024-01-15')];
  const result = dashboard(invoices, '2024-03-15');

  assert.equal(result.ok, true);
  assert.equal(typeof result.value.overdue.count, 'number');
  assert.equal(typeof result.value.overdue.amount, 'number');
});

test('dashboard topCustomers have customerId and due', () => {
  const invoices = [makeIssuedInvoice('C-001', '2024-01-15')];
  const result = dashboard(invoices, '2024-03-15');

  assert.equal(result.ok, true);
  for (const customer of result.value.topCustomers) {
    assert(customer.customerId !== undefined);
    assert.equal(typeof customer.due, 'number');
  }
});

